import re

FIELD = re.compile(r"^(?:(?P<field>\w+)=)?(?P<rest>.*)$")
NODE = re.compile(r"^(?P<node>\w+)\(")


def split_body(text):
    # -> (body, closers): body is the first complete value in text (a node
    # call with balanced parens, a quoted string, or a bare token); closers
    # are the ) and ] that follow it. body is None when the value is unclosed
    # (a multi-line opener).
    depth, i, quote = 0, 0, ""
    while i < len(text):
        c = text[i]
        if quote:
            if c == "\\":
                i += 1
            elif c == quote:
                quote = ""
        elif c in "'\"":
            quote = c
        elif c in "([":
            depth += 1
        elif c in ")]":
            if depth == 0:
                break
            depth -= 1
        elif c == "," and depth == 0:
            break
        i += 1
    if depth:
        return None, ""
    return text[:i], text[i:].replace(",", "").strip()


def parse(lines):
    rows, used, stack = [], [], []

    def owner():
        for kind, item in reversed(stack):
            if kind == "node":
                return item
        return None

    def new_row(field, node, attrs):
        parent = owner()
        if not field:
            for kind, item in reversed(stack):
                if kind == "list":
                    field = item
                    break
        row = {"id": len(rows) + 1, "parent": parent["id"] if parent else "",
               "depth": len([1 for k, _ in stack if k == "node"]), "field": field or "",
               "node": node, "attrs": attrs}
        rows.append(row)
        return row

    for j, ln in enumerate(lines):
        text = ln.strip()
        if not text:
            continue
        m = FIELD.match(text)
        field, rest = m.group("field") or "", m.group("rest")
        body, closers = split_body(rest)
        n = NODE.match(rest)
        if body is None:
            if n:
                stack.append(("node", new_row(field, n.group("node"), "")))
            else:
                stack.append(("list", field))
        elif n:
            new_row(field, n.group("node"), body[len(n.group("node")) + 1:-1])
        else:
            o = owner()
            if o is not None:
                o["attrs"] = (o["attrs"] + ", " + field + "=" + body).strip(", ")
        for c in closers:
            if stack:
                stack.pop()
        used.append(j)
    return [{"name": "nodes", "kind": "table", "lines": used, "records": rows}]
